def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Check all prime numbers up to 63
primes = [n for n in range(2, 64) if is_prime(n)]
print("Primes up to 63:", primes)

# Find pairs of primes that sum to 63
valid_pairs = []
for r1 in primes:
    r2 = 63 - r1
    if r2 in primes and is_prime(r2):
        k = r1 * r2
        valid_pairs.append((r1, r2, k))

print("Valid pairs (r1, r2, k):", valid_pairs)
print("Number of possible values of k:", len(valid_pairs))

possible_primes = set()
for A in range(10, 100):
    for B in range(10, 100):
        if A != B:
            num1 = 10*A + B
            num2 = 10*B + A
            diff = abs(num1 - num2)
            possible_primes.add(diff)

print(f"Possible differences: {sorted(possible_primes)}")
print(f"Prime factors: {sorted(possible_primes)}")

