import math

# Find prime factorization of 135
n1 = 135
f1 = {}
temp = n1
for i in range(2, int(math.sqrt(temp)) + 1):
    while temp % i == 0:
        f1[i] = f1.get(i, 0) + 1
        temp //= i

# Find prime factorization of 468
n2 = 468
f2 = {}
temp = n2
for i in range(2, int(math.sqrt(temp)) + 1):
    while temp % i == 0:
        f2[i] = f2.get(i, 0) + 1
        temp //= i

print(f"Prime factorization of 135: {f1}")
print(f"Prime factorization of 468: {f2}")

# LCM is the product of each prime with the highest power
lcm_prime = 1
for prime, exponent in f1.items():
    lcm_prime *= prime ** (max(exponent, 0))

for prime, exponent in f2.items():
    lcm_prime *= prime ** (max(exponent, 0))

print(f"LCM of 135 and 468: {lcm_prime}")

